import struct,zlib

def load(path):
 data=open(path,'rb').read();pos=8;ids=b''
 while pos<len(data):
  n=struct.unpack('>I',data[pos:pos+4])[0];typ=data[pos+4:pos+8];body=data[pos+8:pos+8+n];pos+=12+n
  if typ==b'IHDR':w,h,depth,mode,*_=struct.unpack('>IIBBBBB',body)
  if typ==b'IDAT':ids+=body
 if depth!=8:raise Exception((w,h,depth,mode))
 bpp={0:1,2:3,4:2,6:4}[mode]; raw=zlib.decompress(ids);rows=[];prev=[0]*(w*bpp);pos=0
 def paeth(a,b,c):
  p=a+b-c;pa=abs(p-a);pb=abs(p-b);pc=abs(p-c)
  return a if pa<=pb and pa<=pc else b if pb<=pc else c
 for y in range(h):
  f=raw[pos];pos+=1;row=list(raw[pos:pos+w*bpp]);pos+=w*bpp
  for i in range(len(row)):
   a=row[i-bpp] if i>=bpp else 0;b=prev[i];c=prev[i-bpp] if i>=bpp else 0
   row[i]=(row[i]+([0,a,b,(a+b)//2,paeth(a,b,c)][f]))&255
  rows.append([tuple(row[i:i+bpp]) for i in range(0,len(row),bpp)]);prev=row
 return w,h,mode,rows
