package main

import (
 "image"
 "image/color"
 "math"
)

// Samples are kept unassociated during filtering, and converted to RGBA only
// when computing the visible color against the terminal's black background.
func toNRGBA(src image.Image)*image.NRGBA{
 b:=src.Bounds();dst:=image.NewNRGBA(image.Rect(0,0,b.Dx(),b.Dy()))
 for y:=0;y<b.Dy();y++{for x:=0;x<b.Dx();x++{dst.SetNRGBA(x,y,color.NRGBAModel.Convert(src.At(x+b.Min.X,y+b.Min.Y)).(color.NRGBA))}}
 return dst
}
func lanczos(x float64)float64{
 if x<0{x=-x};if x<1e-12{return 1};if x>=3{return 0}
 p:=math.Pi*x
 return math.Sin(p)*math.Sin(p/3)/(p*p/3)
}
type weight struct{pos int; value float64}
func makeWeights(src,dst int)[][]weight{
 all:=make([][]weight,dst);ratio:=float64(src)/float64(dst);scale:=math.Max(1,ratio)
 for i:=0;i<dst;i++{
  center:=(float64(i)+.5)*ratio-.5
  lo:=int(math.Ceil(center-3*scale));hi:=int(math.Floor(center+3*scale))
  if lo<0{lo=0};if hi>=src{hi=src-1};sum:=0.0
  for j:=lo;j<=hi;j++{v:=lanczos((float64(j)-center)/scale);if v!=0{all[i]=append(all[i],weight{j,v});sum+=v}}
  for j:=range all[i]{all[i][j].value/=sum}
 }
 return all
}
func roundByte(v float64)uint8{if v<0{return 0};if v>255{return 255};return uint8(v+.5)}
func resizeImage(src *image.NRGBA,w,h int)*image.NRGBA{
 sw,sh:=src.Bounds().Dx(),src.Bounds().Dy()
 if w<0||h<0||sw==0||sh==0||(w==0&&h==0){return image.NewNRGBA(image.Rect(0,0,0,0))}
 if w==0{w=int(math.Floor(float64(h)*float64(sw)/float64(sh)+.5));if w<1{w=1}}
 if h==0{h=int(math.Floor(float64(w)*float64(sh)/float64(sw)+.5));if h<1{h=1}}
 if w>20000 || h>20000 || w*h>50000000 {return image.NewNRGBA(image.Rect(0,0,0,0))}
 if w!=sw{
  out:=image.NewNRGBA(image.Rect(0,0,w,sh));weights:=makeWeights(sw,w)
  for y:=0;y<sh;y++{for x,ws:=range weights{
   r,g,b,a:=0.0,0.0,0.0,0.0
   for _,v:=range ws{p:=src.NRGBAAt(v.pos,y);aw:=float64(p.A)*v.value;r+=float64(p.R)*aw;g+=float64(p.G)*aw;b+=float64(p.B)*aw;a+=aw}
   var c color.NRGBA
   if a!=0{c=color.NRGBA{roundByte(r/a),roundByte(g/a),roundByte(b/a),roundByte(a)}}
   out.SetNRGBA(x,y,c)
  }};src=out
 }
 if h!=sh{
  out:=image.NewNRGBA(image.Rect(0,0,w,h));weights:=makeWeights(sh,h)
  for y,ws:=range weights{for x:=0;x<w;x++{
   r,g,b,a:=0.0,0.0,0.0,0.0
   for _,v:=range ws{p:=src.NRGBAAt(x,v.pos);aw:=float64(p.A)*v.value;r+=float64(p.R)*aw;g+=float64(p.G)*aw;b+=float64(p.B)*aw;a+=aw}
   var c color.NRGBA
   if a!=0{c=color.NRGBA{roundByte(r/a),roundByte(g/a),roundByte(b/a),roundByte(a)}}
   out.SetNRGBA(x,y,c)
  }};src=out
 }
 return src
}
