func loadImage(path string)(image.Image,error){
 var data []byte;var err error;desc:=path
 if path=="-"{
  st,_:=os.Stdin.Stat()
  if st!=nil&&st.Mode()&os.ModeCharDevice!=0{return nil,fmt.Errorf("Error: there is no input being piped to stdin")}
  data,err=io.ReadAll(os.Stdin);desc="piped input"
 }else if strings.HasPrefix(path,"http://")||strings.HasPrefix(path,"https://"){
  var resp *http.Response
  resp,err=http.Get(path);if err==nil{defer resp.Body.Close();data,err=io.ReadAll(resp.Body)}
  if err!=nil{return nil,fmt.Errorf("Error: unable to fetch image: %v",err)}
 }else{
  f,e:=os.Open(path);if e!=nil{return nil,fmt.Errorf("Error: unable to open file: %v",e)}
  defer f.Close();data,err=io.ReadAll(f)
 }
 if err!=nil{data=nil}
 im,_,err:=image.Decode(bytes.NewReader(data))
 if err!=nil{return nil,fmt.Errorf("Error: can't decode %s: %v",desc,err)}
 return im,nil
}
func validateFont(path string)error{
 if path==""{return nil}
 b,err:=os.ReadFile(path)
 if err!=nil{return fmt.Errorf("Error: unable to open font file: %v",err)}
 if len(b)<12{return fmt.Errorf("Error: unable to parse font file: freetype: invalid TrueType format: TTF data is too short")}
 if string(b[:4])!="\x00\x01\x00\x00" && string(b[:4])!="true" {return fmt.Errorf("Error: unable to parse font file: freetype: invalid TrueType format: bad TTF version")}
 return nil
}
func saveName(path string)string{
 if path=="-"{return "piped-img"}
 name:=filepath.Base(path);return strings.TrimSuffix(name,filepath.Ext(name))
}
func savePath(dir,name,ext string)string{if !strings.HasSuffix(dir,"/"){dir+="/"};return dir+name+"-ascii-art."+ext}
func convertPath(path string,o options)error{
 im,err:=loadImage(path);if err!=nil{return err}
 if err=validateFont(o.font);err!=nil{return err}
 colored:=o.color||o.gray||len(o.fontColor)>0
 if colored&&colorMode()==0{return fmt.Errorf("Error: your terminal supports neither 24-bit nor 8-bit colors. Other coloring options aren't available")}
 a:=o.makeArt(im)
